192	impl Debug for SystemDownloader {
193	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
194	        f.debug_struct("SystemDownloader")
195	            .field("user_agent", &self.user_agent)
196	            .finish_non_exhaustive()
197	    }
198	}
